import {Router} from '../utils/router.js';
import {randomUUID} from 'node:crypto';
import {z} from 'zod';
import {pool} from '../config/db.js';
import {requireAuth,allowRoles} from '../middleware/auth.js';
import {requireDepartment,academicAccess} from '../services/academicAccess.js';
import {parseSyllabusPdf,formatSyllabusFilename} from '../services/syllabusPdfParser.js';
import {asyncHandler} from '../utils/asyncHandler.js';
import {splitFourYearStructure} from '../services/hodSyllabusStructure.js';

export const hodRouter=Router();
hodRouter.use(requireAuth);
const uuid=z.string().uuid();
const pdfSchema=z.object({pdf:z.string().min(1).max(35_000_000),fileName:z.string().trim().min(1).max(200),program:z.string().trim().min(2).max(120),regulation:z.string().trim().min(2).max(100),departmentId:uuid});
const subjectInput=z.object({id:uuid.optional(),year:z.number().int().min(1).max(4),semester:z.number().int().min(1).max(8),code:z.string().trim().min(1).max(40),name:z.string().trim().min(2).max(200),type:z.enum(['theory','lab','elective','honours']),credits:z.number().min(0).max(99),periodsPerWeek:z.number().min(0).max(99),sectionsCount:z.number().int().min(1).max(100).optional()});
const fail=(status,message)=>{throw Object.assign(new Error(message),{status});};
async function departmentScope(req,departmentId,db=pool){await requireDepartment(req,departmentId,db);}
async function structureFor(req,id,db=pool){const row=(await db.query('select * from syllabus_structures where id=$1',[id])).rows[0];if(!row)fail(404,'Syllabus structure not found.');await departmentScope(req,row.department_id,db);return row;}
async function sheetFor(req,id,db=pool){const row=(await db.query('select p.*,s.department_id from preference_sheets p join syllabus_structures s on s.id=p.structure_id where p.id=$1',[id])).rows[0];if(!row)fail(404,'Preference sheet not found.');await departmentScope(req,row.department_id,db);return row;}
async function notifyOnce(db,sheetId,eventKey,userId,title,body,link){const inserted=await db.query('insert into hod_notification_events(sheet_id,event_key,recipient_user_id) values($1,$2,$3) on conflict do nothing returning id',[sheetId,eventKey,userId]);if(!inserted.rowCount)return;try{const n=(await db.query('insert into notifications(user_id,title,body,type,link) values($1,$2,$3,\'academic\',$4) returning id',[userId,title,body,link])).rows[0];await db.query('update hod_notification_events set notification_id=$2 where id=$1',[inserted.rows[0].id,n.id]);}catch(error){await db.query('delete from hod_notification_events where id=$1',[inserted.rows[0].id]);throw error;}}
async function facultyRecipients(db,departmentId){return (await db.query('select f.id faculty_id,f.user_id from faculty f join users u on u.id=f.user_id where f.department_id=$1 and u.active order by f.id',[departmentId])).rows;}
async function buildAssignmentSnapshot(db,structure){
 const [subjectsResult,sectionsResult,assignmentsResult]=await Promise.all([
  db.query('select * from semester_subjects where structure_id=$1 order by year,semester,subject_code',[structure.id]),
  db.query('select x.id,x.year_number,x.semester_number,x.section_name,x.academic_year from academic_sections x where x.department_id=$1 and exists(select 1 from semester_subjects ss where ss.structure_id=$2 and ss.year=x.year_number and ss.semester=x.semester_number) order by x.year_number,x.semester_number,x.academic_year,x.section_name',[structure.department_id,structure.id]),
  db.query(`select distinct on(a.semester_subject_id,a.section) a.semester_subject_id,a.section section_id,a.faculty_id,a.confirmed_at,ss.year,ss.semester,ss.subject_code,ss.subject_name,ss.type,ss.credits,ss.periods_per_week,x.section_name,x.academic_year,f.employee_code,u.full_name,coalesce(to_jsonb(f)->>'designation','Faculty') designation,u.email from subject_assignments a join preference_sheets p on p.id=a.sheet_id join semester_subjects ss on ss.id=a.semester_subject_id join academic_sections x on x.id=a.section join faculty f on f.id=a.faculty_id join users u on u.id=f.user_id where p.structure_id=$1 order by a.semester_subject_id,a.section,a.confirmed_at desc nulls last`,[structure.id])
 ]);
 const subjects=subjectsResult.rows,sections=sectionsResult.rows,assignments=assignmentsResult.rows;
 const semesters=Array.from({length:8},(_,index)=>{
  const semester=index+1,year=Math.ceil(semester/2),items=subjects.filter(x=>Number(x.semester)===semester),classes=sections.filter(x=>Number(x.year_number)===year&&Number(x.semester_number)===semester);
  const semesterSubjects=items.map(subject=>{
   const expected=classes;
   const assigned=expected.map(section=>{const row=assignments.find(a=>a.semester_subject_id===subject.id&&a.section_id===section.id);return {sectionId:section.id,sectionName:section.section_name,academicYear:section.academic_year,facultyId:row?.faculty_id||null,facultyName:row?.full_name||null,facultyEmail:row?.email||null,designation:row?.designation||null,confirmed:Boolean(row?.confirmed_at)};});
   return {id:subject.id,code:subject.subject_code,name:subject.subject_name,type:subject.type,credits:Number(subject.credits),periodsPerWeek:Number(subject.periods_per_week),sectionsCount:classes.length,syllabusDocumentId:subject.syllabus_document_id,sections:assigned,assigned:assigned.filter(x=>x.facultyId).length,confirmed:assigned.filter(x=>x.facultyId&&x.confirmed).length,required:assigned.length};
  });
  const required=semesterSubjects.reduce((sum,x)=>sum+x.required,0),assigned=semesterSubjects.reduce((sum,x)=>sum+x.assigned,0),confirmed=semesterSubjects.reduce((sum,x)=>sum+x.confirmed,0);
  return {year,semester,subjects:semesterSubjects,assigned,confirmed,required,complete:semesterSubjects.length>0&&required>0&&confirmed===required};
 });
 const loads=new Map();
 for(const row of assignments){if(!row.confirmed_at)continue;const key=[row.academic_year||'Unspecified academic year',row.semester,row.faculty_id].join('|');const current=loads.get(key)||{academicYear:row.academic_year||'Unspecified academic year',year:Number(row.year),semester:Number(row.semester),facultyId:row.faculty_id,facultyName:row.full_name,email:row.email,designation:row.designation,periods:0,assignments:[]};current.periods+=Number(row.periods_per_week||0);current.assignments.push({year:Number(row.year),semester:Number(row.semester),subjectCode:row.subject_code,subjectName:row.subject_name,section:row.section_name,periods:Number(row.periods_per_week||0)});loads.set(key,current);}
 const teacherLoads=[...loads.values()].sort((a,b)=>a.academicYear.localeCompare(b.academicYear)||a.year-b.year||a.semester-b.semester||a.facultyName.localeCompare(b.facultyName));
 const years=Array.from({length:4},(_,index)=>{const year=index+1,terms=semesters.filter(x=>x.year===year);return {year,semesters:terms,complete:terms.length===2&&terms.every(x=>x.complete)};});
 return {structure:{id:structure.id,program:structure.program,regulation:structure.regulation,departmentId:structure.department_id,department:structure.department||null,version:structure.version||'v1'},semesters,years,teacherLoads,allComplete:years.every(x=>x.complete)&&teacherLoads.every(x=>x.periods<=20),canSubmit:semesters.some(x=>x.complete)&&teacherLoads.every(x=>x.periods<=20),overLimit:teacherLoads.filter(x=>x.periods>20)};
}

async function loadCoordinatorSubmission(id,db=pool){
 const row=(await db.query(`select s.*,d.name department,st.program,st.regulation from hod_assignment_submissions s join syllabus_structures st on st.id=s.structure_id join departments d on d.id=s.department_id where s.id=$1`,[id])).rows[0];
 if(!row)fail(404,'Coordinator submission not found.');
 return {id:row.id,structureId:row.structure_id,departmentId:row.department_id,version:row.version,note:row.note,submittedAt:row.submitted_at,submittedBy:row.submitted_by,department:row.department,program:row.program,regulation:row.regulation,snapshot:row.snapshot};
}

hodRouter.get('/catalog',allowRoles('hod'),asyncHandler(async(req,res)=>{const {departmentIds}=await academicAccess(req);const [departments,sections,faculty]=await Promise.all([pool.query('select id,name from departments where id=any($1::uuid[]) order by name',[departmentIds]),pool.query('select id,department_id,year_number,semester_number,section_name,academic_year from academic_sections where department_id=any($1::uuid[]) order by year_number,semester_number,section_name',[departmentIds]),pool.query(`select f.id,f.department_id,coalesce(to_jsonb(f)->>'designation','Faculty') designation,u.full_name,u.email from faculty f join users u on u.id=f.user_id where f.department_id=any($1::uuid[]) and u.active and exists(select 1 from user_roles ur where ur.user_id=u.id and ur.role='faculty') order by u.full_name`,[departmentIds])]);res.json({departments:departments.rows,sections:sections.rows,faculty:faculty.rows});}));

hodRouter.get('/overview',allowRoles('hod'),asyncHandler(async(req,res)=>{const scope=await academicAccess(req);const d=scope.departmentIds;const {rows}=await pool.query(`select (select count(*)::int from preference_sheets p join syllabus_structures s on s.id=p.structure_id where s.department_id=any($1::uuid[]) and p.status='published') open_sheets,(select count(distinct fp.faculty_id)::int from faculty_preferences fp join preference_sheet_recipients r on r.sheet_id=fp.sheet_id and r.faculty_id=fp.faculty_id join preference_sheets p on p.id=fp.sheet_id join syllabus_structures s on s.id=p.structure_id where s.department_id=any($1::uuid[])) responses,(select count(*)::int from preference_sheets p join syllabus_structures s on s.id=p.structure_id where s.department_id=any($1::uuid[]) and p.status='closed' and exists(select 1 from preference_sheet_subjects ps where ps.sheet_id=p.id) and exists(select 1 from academic_sections x where x.department_id=s.department_id and x.year_number=p.year and x.semester_number=p.semester) and exists(select 1 from preference_sheet_subjects ps where ps.sheet_id=p.id and not exists(select 1 from subject_assignments a where a.sheet_id=p.id and a.semester_subject_id=ps.semester_subject_id))) pending_assignments,(select count(*)::int from syllabus_structures where department_id=any($1::uuid[]) and status='confirmed') confirmed_structures`,[d]);res.json({overview:{openSheets:rows[0].open_sheets,responses:rows[0].responses,pendingAssignments:rows[0].pending_assignments,confirmedStructures:rows[0].confirmed_structures}});}));

hodRouter.post('/structures/upload',allowRoles('hod'),asyncHandler(async(req,res)=>{const p=pdfSchema.safeParse(req.body);if(!p.success)return res.status(400).json({message:'Provide the full syllabus PDF, program, regulation, and department.'});await departmentScope(req,p.data.departmentId);const bytes=Buffer.from(p.data.pdf,'base64');if(!bytes.length||bytes.length>25*1024*1024||bytes.subarray(0,5).toString()!=='%PDF-')fail(400,'Upload a valid PDF no larger than 25 MB.');const matched=await splitFourYearStructure(bytes,{program:p.data.program});if(!matched.length)fail(422,'No subjects with a valid year and semester were detected. Check that the PDF has selectable text and course codes, or use the subject editor to add missing courses.');const db=await pool.connect();try{await db.query('begin');const department=(await db.query('select name from departments where id=$1',[p.data.departmentId])).rows[0];const doc=(await db.query(`insert into syllabi(title,department,batch,description,file_name,pdf,created_by,department_id,status) values($1,$2,$3,$4,$5,$6,$7,$8,'draft') returning id`,[`${p.data.program} syllabus structure ${p.data.regulation}`,department.name,p.data.regulation,'Original four-year source syllabus PDF; subject PDFs are split from detected course boundaries',p.data.fileName,bytes,req.user.sub,p.data.departmentId])).rows[0];const structure=(await db.query(`insert into syllabus_structures(department_id,program,regulation,document_id,uploaded_by) values($1,$2,$3,$4,$5) returning *`,[p.data.departmentId,p.data.program,p.data.regulation,doc.id,req.user.sub])).rows[0];for(const x of matched){const syllabus=(await db.query(`insert into syllabi(title,department,batch,description,file_name,pdf,created_by,department_id,status) values($1,$2,$3,$4,$5,$6,$7,$8,'draft') returning id`,[x.title,department.name,p.data.regulation,`Automatically split from ${p.data.fileName} (pages ${x.item.startPage}-${x.item.endPage})`,formatSyllabusFilename(x.code,x.title),x.pdf,req.user.sub,p.data.departmentId])).rows[0];await db.query(`insert into semester_subjects(structure_id,year,semester,subject_code,subject_name,type,credits,periods_per_week,sections_count,syllabus_document_id) values($1,$2,$3,$4,$5,$6,$7,$8,1,$9)`,[structure.id,x.year,x.semester,x.code,x.title,x.type,x.credits,x.periodsPerWeek,syllabus.id]);}const subjects=(await db.query('select * from semester_subjects where structure_id=$1 order by year,semester,subject_code',[structure.id])).rows;await db.query('commit');res.status(201).json({structure,subjects,detected:subjects.length,splitFromSource:true,semesters:[...new Set(subjects.map(x=>`${x.year}-${x.semester}`))].length});}catch(e){await db.query('rollback');throw e;}finally{db.release();}}));


hodRouter.get('/structures',allowRoles('hod'),asyncHandler(async(req,res)=>{const {departmentIds}=await academicAccess(req);const structures=(await pool.query('select s.*,d.name department,(select count(*)::int from semester_subjects ss where ss.structure_id=s.id) subject_count from syllabus_structures s join departments d on d.id=s.department_id where s.department_id=any($1::uuid[]) order by s.created_at desc nulls last,s.id desc',[departmentIds])).rows;res.json({structures});}));
hodRouter.get('/coordinator-sheets/structures',allowRoles('hod'),asyncHandler(async(req,res)=>{const {departmentIds}=await academicAccess(req);const structures=(await pool.query(`select s.id,s.department_id,s.program,s.regulation,s.status,s.confirmed_at,d.name department,(select count(*)::int from semester_subjects ss where ss.structure_id=s.id) subject_count,latest.id submission_id,latest.version submission_version,latest.submitted_at from syllabus_structures s join departments d on d.id=s.department_id left join lateral(select id,version,submitted_at from hod_assignment_submissions where structure_id=s.id order by version desc limit 1) latest on true where s.department_id=any($1::uuid[]) and s.status='confirmed' order by d.name,s.program,s.regulation,s.confirmed_at desc nulls last`,[departmentIds])).rows;res.json({structures});}));
hodRouter.get('/coordinator-sheets/structures/:id',allowRoles('hod'),asyncHandler(async(req,res)=>{const structure=await structureFor(req,req.params.id);const department=(await pool.query('select name from departments where id=$1',[structure.department_id])).rows[0]?.name;const snapshot=await buildAssignmentSnapshot(pool,{...structure,department});const latest=(await pool.query('select id,version,note,submitted_at from hod_assignment_submissions where structure_id=$1 order by version desc limit 1',[structure.id])).rows[0]||null;res.json({snapshot,latest});}));
hodRouter.post('/coordinator-sheets/structures/:id',allowRoles('hod'),asyncHandler(async(req,res)=>{const parsed=z.object({note:z.string().trim().max(2000).optional().default('')}).safeParse(req.body||{});if(!parsed.success)return res.status(400).json({message:'The coordinator note must be 2,000 characters or fewer.'});const db=await pool.connect();try{await db.query('begin');const structure=(await db.query('select * from syllabus_structures where id=$1 for update',[req.params.id])).rows[0];if(!structure)fail(404,'Syllabus structure not found.');await departmentScope(req,structure.department_id,db);if(structure.status!=='confirmed')fail(409,'Confirm the syllabus structure before sending assignments.');const department=(await db.query('select name from departments where id=$1',[structure.department_id])).rows[0]?.name;const snapshot=await buildAssignmentSnapshot(db,{...structure,department});if(!snapshot.canSubmit){if(!snapshot.semesters.some(x=>x.complete))fail(409,'Confirm every subject section in at least one semester before sending.');if(snapshot.overLimit.length)fail(409,'Teacher workload exceeds 20 periods per week for: '+snapshot.overLimit.map(x=>x.facultyName+' (Year '+x.year+', Semester '+x.semester+': '+x.periods+')').join('; ')+'.');}const coordinators=(await db.query(`select distinct u.id from users u join user_roles ur on ur.user_id=u.id and ur.role='academic_coordinator' where u.active and (exists(select 1 from academic_institution_access ia where ia.user_id=u.id) or exists(select 1 from academic_coordinator_departments cd where cd.user_id=u.id and cd.department_id=$1))`,[structure.department_id])).rows;if(!coordinators.length)fail(409,'No Academic Coordinator has access to this department. Assign coordinator department access, then send again.');const version=Number((await db.query('select coalesce(max(version),0)+1 version from hod_assignment_submissions where structure_id=$1',[structure.id])).rows[0].version);const saved=(await db.query('insert into hod_assignment_submissions(structure_id,department_id,version,snapshot,note,submitted_by) values($1,$2,$3,$4::jsonb,$5,$6) returning id,version,submitted_at',[structure.id,structure.department_id,version,JSON.stringify(snapshot),parsed.data.note,req.user.sub])).rows[0];for(const coordinator of coordinators)await db.query(`insert into notifications(user_id,title,body,type,link) values($1,$2,$3,'academic',$4)`,[coordinator.id,'HOD assignment sheet received',`${department}: ${structure.program} (${structure.regulation}), submission v${version} is ready for review.`, '/academic-coordinator']);await db.query('commit');res.status(201).json({submission:{...saved,department,program:structure.program,regulation:structure.regulation},notified:coordinators.length});}catch(e){await db.query('rollback');throw e;}finally{db.release();}}));

hodRouter.get('/coordinator-submissions',allowRoles('academic_coordinator','admin'),asyncHandler(async(req,res)=>{const access=await academicAccess(req);const submissions=(await pool.query(`select distinct on(s.structure_id) s.id,s.structure_id,s.department_id,s.version,s.note,s.submitted_at,d.name department,st.program,st.regulation from hod_assignment_submissions s join departments d on d.id=s.department_id join syllabus_structures st on st.id=s.structure_id where ($1::boolean or s.department_id=any($2::uuid[])) order by s.structure_id,s.version desc`,[access.institutionWide,access.departmentIds])).rows;submissions.sort((a,b)=>new Date(b.submitted_at)-new Date(a.submitted_at));res.json({submissions});}));
hodRouter.get('/coordinator-submissions/:id',allowRoles('academic_coordinator','admin'),asyncHandler(async(req,res)=>{const submission=await loadCoordinatorSubmission(req.params.id);await requireDepartment(req,submission.departmentId);res.json({submission});}));
hodRouter.get('/structures/:id/subjects',allowRoles('hod'),asyncHandler(async(req,res)=>{const s=await structureFor(req,req.params.id);const subjects=(await pool.query('select ss.*,sy.title syllabus_title,sy.file_name,sy.status syllabus_status from semester_subjects ss left join syllabi sy on sy.id=ss.syllabus_document_id where ss.structure_id=$1 order by ss.year,ss.semester,ss.subject_code',[s.id])).rows;res.json({structure:s,subjects});}));
hodRouter.put('/structures/:id/subjects',allowRoles('hod'),asyncHandler(async(req,res)=>{const p=subjectInput.safeParse(req.body);if(!p.success)return res.status(400).json({message:'Provide valid semester, course details, type, credits, weekly periods, and sections.'});const s=await structureFor(req,req.params.id);const d=p.data;const count=d.sectionsCount||1;try{const rows=d.id?await pool.query('update semester_subjects set year=$2,semester=$3,subject_code=$4,subject_name=$5,type=$6,credits=$7,periods_per_week=$8,sections_count=$9 where id=$1 and structure_id=$10 returning *',[d.id,d.year,d.semester,d.code.toUpperCase(),d.name,d.type,d.credits,d.periodsPerWeek,count,s.id]):await pool.query('insert into semester_subjects(structure_id,year,semester,subject_code,subject_name,type,credits,periods_per_week,sections_count) values($1,$2,$3,$4,$5,$6,$7,$8,$9) returning *',[s.id,d.year,d.semester,d.code.toUpperCase(),d.name,d.type,d.credits,d.periodsPerWeek,count]);if(!rows.rowCount)fail(404,'Subject not found in this draft.');if(s.status==='confirmed')await pool.query("update syllabus_structures set status='draft',confirmed_at=null where id=$1",[s.id]);res.json({subject:rows.rows[0]});}catch(error){if(error.code==='23505')fail(409,`Course code ${d.code.toUpperCase()} already exists in Year ${d.year}, Semester ${d.semester}. Use a unique code or edit the existing subject.`);throw error;}}));
hodRouter.delete('/structures/:id/subjects/:subjectId',allowRoles('hod'),asyncHandler(async(req,res)=>{const s=await structureFor(req,req.params.id);try{const result=await pool.query('delete from semester_subjects where id=$1 and structure_id=$2 returning id',[req.params.subjectId,s.id]);if(!result.rowCount)fail(404,'Subject not found in this draft.');if(s.status==='confirmed')await pool.query("update syllabus_structures set status='draft',confirmed_at=null where id=$1",[s.id]);res.json({message:'Subject deleted. Structure moved to draft; confirm it to apply the changes.'});}catch(error){if(error.code==='23503')fail(409,'This subject is already used by a preference sheet and cannot be deleted.');throw error;}}));
hodRouter.put('/structures/:id/subjects/:subjectId/syllabus',allowRoles('hod'),asyncHandler(async(req,res)=>{const p=z.object({fileName:z.string().trim().min(1).max(200),pdf:z.string().min(1).max(35_000_000)}).safeParse(req.body);if(!p.success)return res.status(400).json({message:'Select a PDF syllabus document.'});const s=await structureFor(req,req.params.id);if(s.status!=='draft')fail(409,'Confirmed structures cannot be edited.');const subject=(await pool.query('select * from semester_subjects where id=$1 and structure_id=$2',[req.params.subjectId,s.id])).rows[0];if(!subject)fail(404,'Subject not found.');const bytes=Buffer.from(p.data.pdf,'base64');if(bytes.subarray(0,5).toString()!=='%PDF-'||bytes.length>25*1024*1024)fail(400,'Upload a valid PDF no larger than 25 MB.');const department=(await pool.query('select name from departments where id=$1',[s.department_id])).rows[0].name;const db=await pool.connect();try{await db.query('begin');let subjectId=subject.subject_id;if(!subjectId){let existing=(await db.query('select id,department_id from subjects where lower(code)=lower($1)',[subject.subject_code])).rows[0];if(existing&&existing.department_id!==s.department_id)fail(409,'This course code belongs to another department.');if(!existing)existing=(await db.query('insert into subjects(code,name,department_id,year_number,semester_number) values($1,$2,$3,$4,$5) returning id,department_id',[subject.subject_code,subject.subject_name,s.department_id,subject.year,subject.semester])).rows[0];subjectId=existing.id;await db.query('update semester_subjects set subject_id=$2 where id=$1',[subject.id,subjectId]);}const doc=(await db.query(`insert into syllabi(title,department,batch,description,file_name,pdf,created_by,department_id,subject_id,status,published_at) values($1,$2,$3,$4,$5,$6,$7,$8,$9,'published',now()) returning id`,[subject.subject_name,department,s.regulation,`Detailed syllabus for ${subject.subject_code}`,p.data.fileName,bytes,req.user.sub,s.department_id,subjectId])).rows[0];await db.query('update semester_subjects set syllabus_document_id=$2 where id=$1',[subject.id,doc.id]);await db.query('commit');res.status(201).json({syllabusDocumentId:doc.id});}catch(e){await db.query('rollback');throw e;}finally{db.release();}}));
hodRouter.post('/structures/:id/confirm',allowRoles('hod'),asyncHandler(async(req,res)=>{const db=await pool.connect();try{await db.query('begin');const s=await structureFor(req,req.params.id,db);const subjects=(await db.query('select * from semester_subjects where structure_id=$1 order by year,semester',[s.id])).rows;if(!subjects.length)fail(400,'Add at least one subject before confirming.');const sections=(await db.query('select id,year_number,semester_number from academic_sections where department_id=$1',[s.department_id])).rows;for(const item of subjects){const existing=await db.query('select id,department_id from subjects where lower(code)=lower($1)',[item.subject_code]);if(existing.rows[0]&&existing.rows[0].department_id!==s.department_id)fail(409,`Subject code ${item.subject_code} is already used by another department.`);const subject=existing.rows[0]|| (await db.query('insert into subjects(code,name,department_id,year_number,semester_number) values($1,$2,$3,$4,$5) returning id',[item.subject_code,item.subject_name,s.department_id,item.year,item.semester])).rows[0];if(existing.rows[0])await db.query('update subjects set name=$2,year_number=$3,semester_number=$4 where id=$1',[subject.id,item.subject_name,item.year,item.semester]);await db.query('update semester_subjects set subject_id=$2 where id=$1',[item.id,subject.id]);for(const section of sections.filter(x=>x.year_number===item.year&&x.semester_number===item.semester))await db.query('insert into section_subjects(academic_section_id,subject_id,subject_type,credits,semester_number,created_by) values($1,$2,$3,$4,$5,$6) on conflict do nothing',[section.id,subject.id,item.type,item.credits,item.semester,req.user.sub]);if(item.syllabus_document_id)await db.query(`update syllabi set subject_id=$2,status='published',published_at=now() where id=$1`,[item.syllabus_document_id,subject.id]);}await db.query(`update syllabus_structures set status='confirmed',confirmed_at=now() where id=$1`,[s.id]);await db.query('commit');res.json({message:'Syllabus structure confirmed.'});}catch(e){await db.query('rollback');throw e;}finally{db.release();}}));

hodRouter.post('/sheets',allowRoles('hod'),asyncHandler(async(req,res)=>{
 const p=z.object({structureId:uuid,year:z.number().int().min(1).max(4),semester:z.number().int().min(1).max(8),deadline:z.string().datetime(),subjectIds:z.array(uuid).min(1).max(100),recipientIds:z.array(uuid).optional(),publish:z.boolean().optional().default(false)}).safeParse(req.body);
 if(!p.success)return res.status(400).json({message:'Choose a confirmed semester, deadline, subjects, and valid recipients.'});
 const s=await structureFor(req,p.data.structureId);
 if(s.status!=='confirmed')fail(409,'Confirm the syllabus structure before creating a preference sheet.');
 const db=await pool.connect();
 try{
  await db.query('begin');
  let sheet,appendToOpen=false;
  const existing=(await db.query('select * from preference_sheets where structure_id=$1 and year=$2 and semester=$3 for update',[s.id,p.data.year,p.data.semester])).rows[0];
  if(existing){
   if(existing.status==='published'){
    if(new Date(existing.deadline)<=new Date())fail(409,'This preference sheet has closed.');
    appendToOpen=true;sheet=existing;
   }else{
    if(existing.status==='closed'&&(await db.query("select 1 from hod_notification_events where sheet_id=$1 and event_key='reopened-once' limit 1",[existing.id])).rowCount)fail(409,'This semester sheet has already used its one-time reopening. Closed semesters cannot be sent again.');
    const activity=(await db.query(`select exists(select 1 from preference_submissions where sheet_id=$1 and submitted_at is not null) submitted,exists(select 1 from subject_assignments where sheet_id=$1) assignments`,[existing.id])).rows[0];
    if(activity.submitted||activity.assignments)fail(409,'This preference sheet already has responses or assignments and cannot be replaced.');
    await db.query('delete from faculty_preferences where sheet_id=$1',[existing.id]);
    await db.query('delete from preference_submissions where sheet_id=$1',[existing.id]);
    await db.query('delete from preference_sheet_subjects where sheet_id=$1',[existing.id]);
    await db.query('delete from preference_sheet_recipients where sheet_id=$1',[existing.id]);
    sheet=(await db.query(`update preference_sheets set deadline=$2,status='draft',published_at=null,closed_at=null where id=$1 returning *`,[existing.id,p.data.deadline])).rows[0];
   }
  }else{
   sheet=(await db.query(`insert into preference_sheets(structure_id,year,semester,deadline,created_by) select $1,$2,$3,$4,$5 where $4>now() returning *`,[s.id,p.data.year,p.data.semester,p.data.deadline,req.user.sub])).rows[0];
   if(!sheet)fail(400,'The deadline must be in the future.');
  }
  if(new Date(p.data.deadline)<=new Date())fail(400,'The deadline must be in the future.');
  let subjectsAdded=0;
  for(const id of p.data.subjectIds){
   const item=(await db.query('select id from semester_subjects where id=$1 and structure_id=$2 and year=$3 and semester=$4',[id,s.id,p.data.year,p.data.semester])).rows[0];
   if(!item)fail(400,'All selected subjects must belong to the chosen semester.');
   const add=await db.query('insert into preference_sheet_subjects(sheet_id,semester_subject_id) values($1,$2) on conflict do nothing returning semester_subject_id',[sheet.id,id]);
   subjectsAdded+=add.rowCount;
  }
  const rec=p.data.recipientIds??(await facultyRecipients(db,s.department_id)).map(x=>x.faculty_id);
  if(!rec.length)fail(400,'Select at least one faculty recipient.');
  const valid=(await db.query(`select f.id from faculty f join users u on u.id=f.user_id where f.id=any($1::uuid[]) and u.active and exists(select 1 from user_roles r where r.user_id=u.id and r.role='faculty')`,[rec])).rows.map(x=>x.id);
  if(valid.length!==new Set(rec).size)fail(400,'Recipients must be active faculty members.');
  let recipientsAdded=0,recipientsRemoved=0;
  if(appendToOpen){const removed=await db.query('delete from preference_sheet_recipients where sheet_id=$1 and not (faculty_id=any($2::uuid[])) returning faculty_id',[sheet.id,valid]);recipientsRemoved=removed.rowCount;}
  for(const id of valid){const added=await db.query('insert into preference_sheet_recipients(sheet_id,faculty_id) values($1,$2) on conflict do nothing returning faculty_id',[sheet.id,id]);recipientsAdded+=added.rowCount;}
  if(appendToOpen&&!subjectsAdded&&!recipientsAdded&&!recipientsRemoved)fail(409,'This sheet already has the selected subjects and exact faculty recipients.');
  if(p.data.publish){
   await db.query(`update preference_sheets set status='published',published_at=now() where id=$1`,[sheet.id]);
   const recipients=(await db.query(`select r.faculty_id,f.user_id from preference_sheet_recipients r join faculty f on f.id=r.faculty_id join users u on u.id=f.user_id where r.sheet_id=$1 and u.active`,[sheet.id])).rows;
   if(!recipients.length)fail(409,'Select at least one recipient before publishing.');
   const eventKey=`${appendToOpen?'update':'publish'}:${randomUUID()}`;
   for(const f of recipients){await db.query('update preference_sheet_recipients set notified_at=now() where sheet_id=$1 and faculty_id=$2',[sheet.id,f.faculty_id]);await notifyOnce(db,sheet.id,eventKey,f.user_id,appendToOpen?'Preference sheet updated':'Faculty subject preferences are open',appendToOpen?`New subject choices were added for Year ${sheet.year}, Semester ${sheet.semester}. You can update your preferences before ${new Date(sheet.deadline).toLocaleString()}.`:`Please submit subject preferences for Year ${sheet.year}, Semester ${sheet.semester} before ${new Date(sheet.deadline).toLocaleString()}.`,'/faculty-dashboard');await db.query("insert into hod_notification_events(sheet_id,event_key,recipient_user_id) values($1,'reopened-once',$2) on conflict do nothing",[sheet.id,f.user_id]);}
  }
  await db.query('commit');
  res.status(201).json({sheet:{...sheet,status:appendToOpen?'published':p.data.publish?'published':'draft',deadline:sheet.deadline},recipients:valid.length,subjectsAdded,recipientsAdded,recipientsRemoved,updated:appendToOpen});
 }catch(e){await db.query('rollback');throw e;}finally{db.release();}
}));
hodRouter.get('/sheets',allowRoles('hod'),asyncHandler(async(req,res)=>{const {departmentIds}=await academicAccess(req);const sheets=(await pool.query(`select p.*,s.id structure_id,d.name department,(select count(distinct fp.faculty_id)::int from faculty_preferences fp join preference_sheet_recipients r on r.sheet_id=fp.sheet_id and r.faculty_id=fp.faculty_id where fp.sheet_id=p.id) responses,(select count(*)::int from preference_sheet_recipients r join faculty f on f.id=r.faculty_id join users u on u.id=f.user_id where r.sheet_id=p.id and u.active) faculty_count,(select coalesce(array_agg(r.faculty_id),'{}'::uuid[]) from preference_sheet_recipients r where r.sheet_id=p.id) recipient_ids from preference_sheets p join syllabus_structures s on s.id=p.structure_id join departments d on d.id=s.department_id where s.department_id=any($1::uuid[]) order by p.created_at desc nulls last,p.id desc`,[departmentIds])).rows;res.json({sheets});}));
hodRouter.post('/sheets/:id/publish',allowRoles('hod'),asyncHandler(async(req,res)=>{const db=await pool.connect();try{await db.query('begin');const sheet=await sheetFor(req,req.params.id,db);if(sheet.status!=='draft'||new Date(sheet.deadline)<=new Date())fail(409,'Only a draft with a future deadline can be published.');const recipients=(await db.query(`select r.faculty_id,f.user_id from preference_sheet_recipients r join faculty f on f.id=r.faculty_id join users u on u.id=f.user_id where r.sheet_id=$1 and u.active`,[sheet.id])).rows;if(!recipients.length)fail(409,'Select at least one recipient before publishing.');await db.query(`update preference_sheets set status='published',published_at=now() where id=$1`,[sheet.id]);for(const f of recipients){await db.query('update preference_sheet_recipients set notified_at=now() where sheet_id=$1 and faculty_id=$2',[sheet.id,f.faculty_id]);await notifyOnce(db,sheet.id,'publish',f.user_id,'Faculty subject preferences are open',`Please submit subject preferences for Year ${sheet.year}, Semester ${sheet.semester} before ${new Date(sheet.deadline).toLocaleString()}.`,'/faculty-dashboard');await db.query("insert into hod_notification_events(sheet_id,event_key,recipient_user_id) values($1,'reopened-once',$2) on conflict do nothing",[sheet.id,f.user_id]);}await db.query('commit');res.json({message:`Published to ${recipients.length} faculty members.`});}catch(e){await db.query('rollback');throw e;}finally{db.release();}}));
hodRouter.post('/sheets/:id/close',allowRoles('hod'),asyncHandler(async(req,res)=>{const sheet=await sheetFor(req,req.params.id);if(sheet.status!=='published')fail(409,'Only a published sheet can be closed.');await pool.query(`update preference_sheets set status='closed',closed_at=now() where id=$1`,[sheet.id]);res.json({message:'Preference sheet closed.'});}));
hodRouter.get('/sheets/:id/preferences',allowRoles('hod'),asyncHandler(async(req,res)=>{const sheet=await sheetFor(req,req.params.id);const [subjects,faculty,preferences,allocations]=await Promise.all([pool.query(`select ss.* from preference_sheet_subjects p join semester_subjects ss on ss.id=p.semester_subject_id where p.sheet_id=$1 order by ss.subject_code`,[sheet.id]),pool.query(`select f.id faculty_id,u.full_name,u.email,coalesce(to_jsonb(f)->>'designation','Faculty') designation from preference_sheet_recipients r join faculty f on f.id=r.faculty_id join users u on u.id=f.user_id where r.sheet_id=$1 order by u.full_name`,[sheet.id]),pool.query(`select f.id faculty_id,u.full_name,sub.remarks,sub.submitted_at from preference_sheet_recipients r join faculty f on f.id=r.faculty_id join users u on u.id=f.user_id left join preference_submissions sub on sub.sheet_id=r.sheet_id and sub.faculty_id=r.faculty_id where r.sheet_id=$1 order by u.full_name`,[sheet.id]),pool.query(`select a.semester_subject_id,a.section section_id,a.faculty_id,ss.subject_code,ss.subject_name,x.section_name from subject_assignments a join semester_subjects ss on ss.id=a.semester_subject_id join academic_sections x on x.id=a.section where a.sheet_id=$1`,[sheet.id])]);const choices=(await pool.query(`select fp.faculty_id,fp.semester_subject_id,fp.rank from faculty_preferences fp join preference_sheet_recipients r on r.sheet_id=fp.sheet_id and r.faculty_id=fp.faculty_id where fp.sheet_id=$1`,[sheet.id])).rows;const preferenceRows=preferences.rows.map(f=>{const row={...f,pref1:null,pref2:null,pref3:null,elective:null};for(const p of choices.filter(x=>x.faculty_id===f.faculty_id)){if(p.rank===1)row.pref1=p.semester_subject_id;if(p.rank===2)row.pref2=p.semester_subject_id;if(p.rank===3)row.pref3=p.semester_subject_id;if(p.rank===4)row.elective=p.semester_subject_id;}return row;});const counts=Object.fromEntries(subjects.rows.map(s=>[s.id,choices.filter(c=>c.semester_subject_id===s.id).length]));res.json({subjects:subjects.rows,faculty:preferences.rows,preferenceRows,counts,allocations:allocations.rows});}));

hodRouter.post('/sheets/:id/assignments/save',allowRoles('hod'),asyncHandler(async(req,res)=>{
 const p=z.object({assignments:z.array(z.object({semesterSubjectId:uuid,sectionId:uuid,facultyId:uuid})).max(300)}).safeParse(req.body);
 if(!p.success)return res.status(400).json({message:'Provide valid subject, section, and faculty selections.'});
 const db=await pool.connect();
 try{
  await db.query('begin');
  const sheet=(await db.query('select p.*,s.department_id from preference_sheets p join syllabus_structures s on s.id=p.structure_id where p.id=$1 for update of p',[req.params.id])).rows[0];
  if(!sheet)fail(404,'Preference sheet not found.');
  await departmentScope(req,sheet.department_id,db);
  if(sheet.status==='draft')fail(409,'Publish the preference sheet before saving assignments.');
  if(sheet.assignments_confirmed_at)fail(409,'Assignments are already confirmed and cannot be changed.');
  if((await db.query('select 1 from subject_assignments where sheet_id=$1 and confirmed_at is not null limit 1',[sheet.id])).rowCount)fail(409,'This sheet already has confirmed assignments. Refresh the page.');
  const structure=await structureFor(req,sheet.structure_id,db);
  const subjects=new Set((await db.query('select ss.id from preference_sheet_subjects pss join semester_subjects ss on ss.id=pss.semester_subject_id where pss.sheet_id=$1 and ss.structure_id=$2 and ss.year=$3 and ss.semester=$4',[sheet.id,structure.id,sheet.year,sheet.semester])).rows.map(x=>x.id));
  const sectionIds=new Set((await db.query('select id from academic_sections where department_id=$1 and year_number=$2 and semester_number=$3',[sheet.department_id,sheet.year,sheet.semester])).rows.map(x=>x.id));
  const seen=new Set();
  for(const a of p.data.assignments){
   const key=a.semesterSubjectId+':'+a.sectionId;
   if(seen.has(key)||!subjects.has(a.semesterSubjectId)||!sectionIds.has(a.sectionId))fail(400,'Each selection must be a unique subject and class from this preference sheet.');
   seen.add(key);
   if(!(await db.query('select 1 from faculty f join users u on u.id=f.user_id where f.id=$1 and f.department_id=$2 and u.active',[a.facultyId,sheet.department_id])).rowCount)fail(400,'Choose an active faculty member from this department.');
  }
  await db.query('delete from subject_assignments where sheet_id=$1 and confirmed_at is null',[sheet.id]);
  for(const a of p.data.assignments)await db.query('insert into subject_assignments(sheet_id,semester_subject_id,section,faculty_id,assigned_by,confirmed_at) values($1,$2,$3,$4,$5,null)',[sheet.id,a.semesterSubjectId,a.sectionId,a.facultyId,req.user.sub]);
  await db.query('commit');
  res.json({message:'Assignment selections saved. You can return later to finish them.',saved:p.data.assignments.length});
 }catch(e){await db.query('rollback');throw e;}finally{db.release();}
}));

hodRouter.post('/sheets/:id/assignments/confirm',allowRoles('hod'),asyncHandler(async(req,res)=>{
 const p=z.object({assignments:z.array(z.object({semesterSubjectId:uuid,sectionId:uuid,facultyId:uuid})).min(1).max(300)}).safeParse(req.body);
 if(!p.success)return res.status(400).json({message:'Provide valid subject, section, and faculty assignments.'});
 const db=await pool.connect();
 try{
  await db.query('begin');
  const sheet=(await db.query('select p.*,s.department_id from preference_sheets p join syllabus_structures s on s.id=p.structure_id where p.id=$1 for update of p',[req.params.id])).rows[0];
  if(!sheet)fail(404,'Preference sheet not found.');
  await departmentScope(req,sheet.department_id,db);
  if(sheet.status==='draft')fail(409,'Publish the preference sheet before confirming assignments.');
  if(sheet.assignments_confirmed_at){await db.query('commit');return res.json({alreadyConfirmed:true,message:'Assignments were already confirmed. No changes were made.'});}
  const structure=await structureFor(req,sheet.structure_id,db);
  const expected=(await db.query('select pss.semester_subject_id,section.id section_id from preference_sheet_subjects pss join semester_subjects ss on ss.id=pss.semester_subject_id join academic_sections section on section.department_id=$2 and section.year_number=$3 and section.semester_number=$4 where pss.sheet_id=$1 and ss.structure_id=$5 and ss.year=$3 and ss.semester=$4',[sheet.id,sheet.department_id,sheet.year,sheet.semester,structure.id])).rows;
  const expectedKeys=new Set(expected.map(x=>x.semester_subject_id+':'+x.section_id));
  const requestedKeys=new Set(p.data.assignments.map(x=>x.semesterSubjectId+':'+x.sectionId));
  if(expectedKeys.size!==p.data.assignments.length||requestedKeys.size!==p.data.assignments.length||[...expectedKeys].some(key=>!requestedKeys.has(key)))fail(409,'Assign every subject to every class section before confirming.');
  const notices=new Map();
  for(const a of p.data.assignments){
   const subject=(await db.query('select * from semester_subjects where id=$1 and structure_id=$2 and year=$3 and semester=$4',[a.semesterSubjectId,structure.id,sheet.year,sheet.semester])).rows[0];
   const section=(await db.query('select * from academic_sections where id=$1 and department_id=$2 and year_number=$3 and semester_number=$4',[a.sectionId,sheet.department_id,sheet.year,sheet.semester])).rows[0];
   const faculty=(await db.query('select f.id,f.department_id,f.user_id from faculty f join users u on u.id=f.user_id where f.id=$1 and f.department_id=$2 and u.active',[a.facultyId,sheet.department_id])).rows[0];
   if(!subject||!section||!faculty)fail(400,'Each subject, section, and faculty member must match the HOD department and selected semester.');
   const subj=(await db.query('select id from subjects where lower(code)=lower($1)',[subject.subject_code])).rows[0];
   if(!subj)fail(409,'Confirm the syllabus structure before assigning '+subject.subject_code+'.');
   await db.query('insert into section_subjects(academic_section_id,subject_id,subject_type,credits,semester_number,created_by) values($1,$2,$3,$4,$5,$6) on conflict do nothing',[section.id,subj.id,subject.type,subject.credits,sheet.semester,req.user.sub]);
   await db.query("insert into faculty_section_assignments(faculty_id,department_id,year_number,semester_number,academic_section_id,subject_id,academic_year,status,created_by) values($1,$2,$3,$4,$5,$6,$7,'active',$8) on conflict(academic_section_id,subject_id) do update set faculty_id=excluded.faculty_id,status='active',created_by=excluded.created_by,updated_at=now()",[faculty.id,sheet.department_id,sheet.year,sheet.semester,section.id,subj.id,section.academic_year,req.user.sub]);
   await db.query('insert into subject_assignments(sheet_id,semester_subject_id,section,faculty_id,assigned_by,confirmed_at) values($1,$2,$3,$4,$5,now()) on conflict(sheet_id,semester_subject_id,section) do update set faculty_id=excluded.faculty_id,assigned_by=excluded.assigned_by,confirmed_at=now()',[sheet.id,subject.id,section.id,faculty.id,req.user.sub]);
   notices.set(faculty.id,{userId:faculty.user_id,body:'Your semester subject allocation for Year '+sheet.year+', Semester '+sheet.semester+' has been confirmed.'});
  }
  for(const [facultyId,n] of notices)await notifyOnce(db,sheet.id,'assignment:'+facultyId,n.userId,'Your semester subject allocation is confirmed',n.body,'/faculty-dashboard');
  await db.query("update preference_sheets set status='closed',closed_at=coalesce(closed_at,now()),assignments_confirmed_at=now() where id=$1",[sheet.id]);
  await db.query('commit');
  res.json({message:'Assignments confirmed once. The preference sheet is now closed and faculty have been notified.'});
 }catch(e){await db.query('rollback');throw e;}finally{db.release();}
}));

hodRouter.get('/faculty/preferences',allowRoles('faculty'),asyncHandler(async(req,res)=>{const faculty=(await pool.query('select id,department_id from faculty where user_id=$1',[req.user.sub])).rows[0];if(!faculty)fail(403,'Your faculty profile is not set up.');const sheets=(await pool.query(`select p.id sheet_id,p.year,p.semester,p.deadline,p.status,s.program,s.regulation,d.name department,ss.id subject_id,ss.subject_code,ss.subject_name,ss.type,ss.credits,ss.periods_per_week,ss.syllabus_document_id,sy.file_name,fp.rank,sub.remarks,sub.submitted_at from preference_sheets p join syllabus_structures s on s.id=p.structure_id join departments d on d.id=s.department_id join preference_sheet_recipients r on r.sheet_id=p.id and r.faculty_id=$1 join preference_sheet_subjects pss on pss.sheet_id=p.id join semester_subjects ss on ss.id=pss.semester_subject_id left join syllabi sy on sy.id=ss.syllabus_document_id left join faculty_preferences fp on fp.sheet_id=p.id and fp.faculty_id=$1 and fp.semester_subject_id=ss.id left join preference_submissions sub on sub.sheet_id=p.id and sub.faculty_id=$1 where (p.status='published' or exists(select 1 from subject_assignments a where a.sheet_id=p.id and a.faculty_id=$1)) order by p.deadline,ss.subject_code`,[faculty.id])).rows;const allocations=(await pool.query(`select a.id,a.sheet_id,a.confirmed_at,p.year,p.semester,ss.subject_code,ss.subject_name,ss.type,ss.credits,ss.periods_per_week,x.section_name,x.academic_year,sy.id syllabus_document_id,sy.file_name from subject_assignments a join preference_sheets p on p.id=a.sheet_id join semester_subjects ss on ss.id=a.semester_subject_id join academic_sections x on x.id=a.section join syllabus_structures st on st.id=p.structure_id left join syllabi sy on sy.id=ss.syllabus_document_id where a.faculty_id=$1 and a.confirmed_at is not null order by a.confirmed_at desc`,[faculty.id])).rows;const assignedSubjects=(await pool.query(`select fa.subject_id,su.code subject_code,su.name subject_name,fa.department_id,d.name department,fa.year_number as "year",fa.semester_number as "semester",x.section_name,x.academic_year,sy.id syllabus_document_id,sy.file_name from faculty_section_assignments fa join subjects su on su.id=fa.subject_id join academic_sections x on x.id=fa.academic_section_id join departments d on d.id=fa.department_id left join lateral(select id,file_name from syllabi where subject_id=su.id and status='published' order by published_at desc nulls last limit 1) sy on true where fa.faculty_id=$1 and fa.status='active' order by fa.year_number,fa.semester_number,x.section_name,su.code`,[faculty.id])).rows;res.json({sheets,allocations,assignedSubjects});}));
hodRouter.put('/faculty/preferences/:sheetId',allowRoles('faculty'),asyncHandler(async(req,res)=>{const p=z.object({rankedSubjectIds:z.array(uuid).min(3).max(3),electiveSubjectId:uuid.nullable().optional(),remarks:z.string().max(2000).optional().default(''),submit:z.boolean().optional().default(true)}).safeParse(req.body);if(!p.success||new Set([...p.data?.rankedSubjectIds||[],...(p.data?.electiveSubjectId?[p.data.electiveSubjectId]:[])]).size!==3+(p.data?.electiveSubjectId?1:0))return res.status(400).json({message:'Choose three distinct ranked subjects and an optional distinct elective.'});const faculty=(await pool.query('select id,department_id from faculty where user_id=$1',[req.user.sub])).rows[0];if(!faculty)fail(403,'Your faculty profile is not set up.');const db=await pool.connect();try{await db.query('begin');const sheet=(await db.query(`select p.*,s.department_id from preference_sheets p join syllabus_structures s on s.id=p.structure_id where p.id=$1 for update`,[req.params.sheetId])).rows[0];if(!sheet)fail(404,'Preference sheet not found.');if(sheet.status!=='published'||new Date(sheet.deadline)<=new Date())fail(409,'This preference sheet is closed.');if(!(await db.query('select 1 from preference_sheet_recipients where sheet_id=$1 and faculty_id=$2',[sheet.id,faculty.id])).rowCount)fail(403,'You are not a recipient of this preference sheet.');const ids=[...p.data.rankedSubjectIds,...(p.data.electiveSubjectId?[p.data.electiveSubjectId]:[])];const open=(await db.query(`select ss.id,ss.type from preference_sheet_subjects x join semester_subjects ss on ss.id=x.semester_subject_id where x.sheet_id=$1`,[sheet.id])).rows;if(ids.some(id=>!open.some(s=>s.id===id)))fail(400,'Choose only subjects open in this preference sheet.');if(p.data.electiveSubjectId&&open.find(s=>s.id===p.data.electiveSubjectId)?.type!=='elective')fail(400,'Choose an elective subject for the elective preference.');await db.query('delete from faculty_preferences where sheet_id=$1 and faculty_id=$2',[sheet.id,faculty.id]);for(let i=0;i<ids.length;i++)await db.query('insert into faculty_preferences(sheet_id,faculty_id,semester_subject_id,rank,remarks,submitted_at) values($1,$2,$3,$4,$5,$6)',[sheet.id,faculty.id,ids[i],i+1,p.data.remarks,p.data.submit?new Date():null]);await db.query(`insert into preference_submissions(sheet_id,faculty_id,remarks,submitted_at) values($1,$2,$3,$4) on conflict(sheet_id,faculty_id) do update set remarks=excluded.remarks,submitted_at=excluded.submitted_at`,[sheet.id,faculty.id,p.data.remarks,p.data.submit?new Date():null]);await db.query('update preference_sheet_recipients set submitted_at=$3 where sheet_id=$1 and faculty_id=$2',[sheet.id,faculty.id,p.data.submit?new Date():null]);await db.query('commit');res.json({message:p.data.submit?'Preferences submitted.':'Draft saved.'});}catch(e){await db.query('rollback');throw e;}finally{db.release();}}));
hodRouter.get('/syllabus/:id/pdf',allowRoles('faculty'),asyncHandler(async(req,res)=>{const row=(await pool.query(`select sy.pdf,sy.file_name from syllabi sy join semester_subjects ss on ss.syllabus_document_id=sy.id join preference_sheet_subjects pss on pss.semester_subject_id=ss.id join preference_sheets ps on ps.id=pss.sheet_id join preference_sheet_recipients r on r.sheet_id=ps.id join faculty f on f.id=r.faculty_id where sy.id=$1 and sy.status='published' and ps.status='published' and f.user_id=$2`,[req.params.id,req.user.sub])).rows[0];if(!row?.pdf)fail(404,'Syllabus document is unavailable.');res.set({'Content-Type':'application/pdf','Content-Disposition':`inline; filename="${formatSyllabusFilename('',row.file_name||'syllabus.pdf')}"`,'Cache-Control':'private, no-store'});res.send(row.pdf);}));

export async function startHodPreferenceWorker(){let busy=false;async function tick(){if(busy)return;busy=true;try{const db=await pool.connect();try{await db.query('begin');const due=(await db.query(`select p.*,s.department_id from preference_sheets p join syllabus_structures s on s.id=p.structure_id where p.status='published' and p.deadline<=now() order by p.deadline limit 50 for update of p skip locked`)).rows;for(const sheet of due)await db.query(`update preference_sheets set status='closed',closed_at=coalesce(closed_at,now()) where id=$1`,[sheet.id]);await db.query('commit');}catch(e){await db.query('rollback');throw e;}finally{db.release();}
 const reminders=await pool.connect();try{await reminders.query('begin');const due=(await reminders.query(`select p.*,s.department_id from preference_sheets p join syllabus_structures s on s.id=p.structure_id where p.status='published' and p.deadline>now() and p.deadline<=now()+interval '24 hours' order by p.deadline limit 50 for update of p skip locked`)).rows;for(const sheet of due){const recipients=(await reminders.query('select f.id faculty_id,f.user_id from preference_sheet_recipients r join faculty f on f.id=r.faculty_id join users u on u.id=f.user_id where r.sheet_id=$1 and u.active',[sheet.id])).rows;for(const f of recipients)if(!(await reminders.query('select 1 from faculty_preferences where sheet_id=$1 and faculty_id=$2',[sheet.id,f.faculty_id])).rowCount)await notifyOnce(reminders,sheet.id,'reminder-24h',f.user_id,'Reminder: subject preferences due soon',`Submit your preferences for Year ${sheet.year}, Semester ${sheet.semester} before ${new Date(sheet.deadline).toLocaleString()}.`,'/faculty-dashboard');}await reminders.query('commit');}catch(e){await reminders.query('rollback');throw e;}finally{reminders.release();}}catch(e){console.error('HOD preference worker failed:',e.code||e.message);}finally{busy=false;}}const timer=setInterval(tick,60000);timer.unref();await tick();return()=>clearInterval(timer);}
